<?php require __DIR__.'/../config/config.php';$u=login_required();if(!has_moderation_consent($pdo,(int)$u['id']))json_out(['error'=>'Please accept the RAAZ privacy and moderation notice in the dashboard first.'],403);check_csrf();$peer=(int)($_POST['user_id']??0);if(!$peer||$peer===$u['id'])json_out(['error'=>'Invalid user'],422);$s=$pdo->prepare("SELECT id FROM users WHERE id=? AND account_status='active'");$s->execute([$peer]);if(!$s->fetch())json_out(['error'=>'User unavailable'],404);
$q=$pdo->prepare("SELECT c.id FROM conversations c JOIN conversation_members a ON a.conversation_id=c.id AND a.user_id=? JOIN conversation_members b ON b.conversation_id=c.id AND b.user_id=? LIMIT 1");$q->execute([$u['id'],$peer]);$id=$q->fetchColumn();if(!$id){$pdo->beginTransaction();try{$pdo->exec('INSERT INTO conversations() VALUES()');$id=(int)$pdo->lastInsertId();$m=$pdo->prepare('INSERT INTO conversation_members(conversation_id,user_id) VALUES(?,?),(?,?)');$m->execute([$id,$u['id'],$id,$peer]);$pdo->commit();}catch(Throwable $e){$pdo->rollBack();throw $e;}}json_out(['conversation_id'=>(int)$id]);